NOTE_S12_HEAD = "\\subsection*{Supplementary note S12: Design of the observability-overhead experiment (original text of Section~\\ref{subsec3.1})}\n"


def rx(text):
    return re.compile(r"\s+".join(re.escape(t) for t in text.split()))


def load(p):
    raw = open(p, "rb").read(); return raw, b"\r\n" in raw, raw.decode("utf-8").replace("\r\n", "\n")


raw, crlf, s = load(P); araw, acrlf, a = load(A)
nrm = lambda z: " ".join(z.split()); state = []
for n, (old, new) in enumerate(PAIRS, 1):
    co, cn = len(rx(old).findall(s)), len(rx(new).findall(s))
    if co == 1 and cn == 0: state.append("old")
    elif cn >= 1 and (co == 0 or nrm(old) in nrm(new)): state.append("new")
    else: sys.exit(f"ABORT: pasangan {n}: teks lama cocok {co} kali, teks baru {cn} kali; tidak ada yang ditulis")
state.append("new" if NOTE_S12_HEAD in a else ("old" if a.count("\\bibliography{sn-bibliography}") == 1 else sys.exit("ABORT: jangkar AF1 tidak unik")))
if all(x == "new" for x in state):
    print("SUDAH TERPASANG: semua", len(PAIRS) + 1, "suntingan; tidak ada yang ditulis"); sys.exit(0)
if any(x == "new" for x in state):
    sys.exit("ABORT: keadaan campuran; tidak ada yang ditulis")
for n, (old, new) in enumerate(PAIRS, 1):
    s, k = rx(old).subn(lambda m, new=new: new, s, count=1)
    if k != 1: sys.exit(f"ABORT: pasangan {n} gagal; tidak ada yang ditulis")
old_body = OLD31.split("\\label{subsec3.1}", 1)[1].strip()
a = a.replace("\\bibliography{sn-bibliography}", NOTE_S12_HEAD + old_body + "\n\n\\bibliography{sn-bibliography}", 1)
for p, r0, c, txt in ((P, raw, crlf, s), (A, araw, acrlf, a)):
    open(p + ".pre-round3.bak", "wb").write(r0); open(p, "wb").write((txt.replace("\n", "\r\n") if c else txt).encode("utf-8"))
print("OK", len(PAIRS), "suntingan naskah + catatan S12 |", "CRLF" if crlf else "LF", "| cadangan .pre-round3.bak")
